    """Parse one SGF game tree, decoding every property value as SGF Text."""
    position = 0

    def peek():
        return input_string[position] if position < len(input_string) else ""

    def parse_value():
        nonlocal position
        position += 1  # Opening bracket.
        value = []
        while position < len(input_string):
            character = input_string[position]
            position += 1
            if character == "]":
                return "".join(value)
            if character == "\\":
                if position == len(input_string):
                    break
                character = input_string[position]
                position += 1
                if character == "\n":
                    continue
            if character != "\n" and character.isspace():
                character = " "
            value.append(character)
        raise ValueError("properties without delimiter")

    def parse_node():
        nonlocal position
        position += 1  # Node marker.
        properties = {}
        while peek() and peek() not in (";", "(", ")"):
