        if peek() != "(":
            raise ValueError("tree missing")
        position += 1
        if peek() != ";":
            raise ValueError("tree with no nodes")
        root = current = parse_node()
        while peek() == ";":
            child = parse_node()
            current.children.append(child)
            current = child
        while peek() == "(":
            current.children.append(parse_tree())
        if peek() != ")":
            raise ValueError("tree missing")
        position += 1
        return root

    tree = parse_tree()
    if position != len(input_string):
        raise ValueError("tree missing")
    return tree
